command:
bash -lc 'set -e; cat > /etc/nginx/sites-available/default << "NGCONF"
server {
  listen 80 default_server;
  listen [::]:80 default_server;
  server_name _;
  root /var/www/html;
  location /noVNC/ {
    alias /var/www/noVNC/;
    index vnc.html;
    try_files $uri $uri/ =404;
  }
  location /websockify/ {
    proxy_pass http://example.com;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "Upgrade";
    proxy_read_timeout 600s;
  }
  location / { return 404; }
}
NGCONF
ln -sf /etc/nginx/sites-available/default /etc/nginx/sites-enabled/default; nginx -s reload || service nginx reload || true; sleep 0.3; curl -sI http://example.com | head -n 5; ss -tlnp | egrep "6080|5901|5555"; printf "sendkey ctrl-alt-delete\n" | nc 1.1.1.1 5555'
